function dateRankingTable(title,rows,label){return `<section class="date-ranking-card"><h3>${title}</h3>${rows.length?`<div class="table-wrap"><table class="date-ranking-table"><thead><tr><th>Rank</th><th>${label}</th><th>Games</th><th>Day scoring average</th><th>Win %</th></tr></thead><tbody>${rows.map((row,index)=>`<tr><td>${index+1}</td><td>${esc(row.name)}</td><td>${row.played}</td><td>${row.average.toFixed(1)}</td><td>${(row.winRate*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">No completed games to rank.</p>'}</section>`;}
